import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {newGame,save,restore} from './simulation.js';
import {introduce} from './identity.js';
import {generateDialogueTurn} from './dialogue-generator.js';
import {thinkingCampaign} from './survival-thinking-fixtures.js';
import {survivalThinkingView,thinkingPlanLine,respondSurvivalThinking} from './survival-thinking.js';
import {backgroundSheets,backdropGeometry,backdropFit,backdropVariables} from './place-backgrounds.js';
test('spoken reasoning uses complete conversational clauses without broken nominal grammar',()=>{for(const [id,topic] of [['yeogyeong','checking'],['yeogyeong','roles'],['seoyeon','self-directed'],['seoyeon','rest'],['soyul','speaking'],['soyul','photo']])for(let seed=1;seed<30;seed++){const s=newGame();s.clock.minute=820;introduce(s,id,'test');s.dialogue.generation={rng:seed*1234567,sequence:0,recent:{}};const r=generateDialogueTurn(s,id,{topic,action:'why'});assert.equal(r.plan.topic,topic);assert.ok(!/undefined|하는 것부터|좋겠어요아서요|좋을 것 같아서요아서요|결과를 인정|선택권을 존중/.test(r.text),r.text);assert.deepEqual(restore(save(s)),s);}});
test('companion speech leaves numeric evidence on the status card instead of reading meters or game rules aloud',()=>{const s=thinkingCampaign(),p=survivalThinkingView(s).find(p=>p.speaker==='ally'),before=save(s);assert.match(p.evidence,/20/);assert.match(thinkingPlanLine(s,p),/물.*먹.*상처/);for(const topic of ['proposal','why','risk','accepted','deferred'])assert.ok(!/\d+\/100|여력|행동력|실제로|관찰|단계|실행 순서/.test(thinkingPlanLine(s,p,topic)));assert.equal(save(s),before);const talked=respondSurvivalThinking(s,p.id,'why');assert.equal(talked.survivalRun.actions,s.survivalRun.actions);assert.deepEqual(talked.relations,s.relations);});
test('native background metadata matches the real PNG files, including commerce two-column tiles',()=>{const files={campus:'campus-place-backgrounds.png',life:'life-place-backgrounds.png',surroundings:'surroundings-place-backgrounds.png',specialist:'academic-interiors-specialist.png',common:'academic-interiors-common.png',commerce:'commerce-interiors.png'};for(const [set,sheet] of Object.entries(backgroundSheets)){const png=readFileSync(new URL('../docs/assets/'+files[set],import.meta.url));assert.equal(png.readUInt32BE(16),sheet.width);assert.equal(png.readUInt32BE(20),sheet.height);const g=backdropGeometry({set});assert.equal(g.width*sheet.columns,sheet.width);assert.equal(g.height*sheet.rows,sheet.height);assert.ok(backdropVariables({set}).includes('--scene-ratio:'));}});
test('whole background fits mobile and wide screens without stretching, cropping or excessive enlargement',()=>{for(const set of Object.keys(backgroundSheets))for(const [width,height] of [[320,720],[390,844],[1440,1000],[2560,1440]]){const g=backdropGeometry({set}),f=backdropFit({set},width,height);assert.ok(f.width<=width+.01);assert.ok(f.height<=height*.72+.01);assert.ok(f.scale<=1.6);assert.ok(Math.abs(f.width/f.height-g.ratio)<1e-8);}});
